import React, { useState, useEffect } from 'react'

export default function PWAInstallPrompt() {
  const [show, setShow] = useState(false)
  const [platform, setPlatform] = useState(null)
  const [deferredPrompt, setDeferredPrompt] = useState(null)

  useEffect(() => {
    // Check if already running as PWA
    const isStandalone =
      window.matchMedia('(display-mode: standalone)').matches ||
      window.navigator.standalone === true ||
      document.referrer.includes('android-app://')

    if (isStandalone) return

    // Detect platform
    const ua = navigator.userAgent
    const isIOS = /iPad|iPhone|iPod/.test(ua) && !window.MSStream
    const isAndroid = /Android/.test(ua)
    const isMobile = isIOS || isAndroid

    if (!isMobile) {
      // Desktop — show after 3 seconds
      setTimeout(() => { setPlatform('desktop'); setShow(true) }, 3000)
      return
    }

    if (isIOS) {
      const dismissed = localStorage.getItem('pwa_dismissed')
      if (!dismissed) { setPlatform('ios'); setShow(true) }
    } else if (isAndroid) {
      window.addEventListener('beforeinstallprompt', (e) => {
        e.preventDefault()
        setDeferredPrompt(e)
        const dismissed = localStorage.getItem('pwa_dismissed')
        if (!dismissed) { setPlatform('android'); setShow(true) }
      })
    }
  }, [])

  function dismiss() {
    localStorage.setItem('pwa_dismissed', '1')
    setShow(false)
  }

  async function installAndroid() {
    if (deferredPrompt) {
      deferredPrompt.prompt()
      const { outcome } = await deferredPrompt.userChoice
      if (outcome === 'accepted') setShow(false)
    }
  }

  if (!show) return null

  return (
    <div style={s.overlay}>
      <div style={s.sheet}>
        <button style={s.closeBtn} onClick={dismiss}>✕</button>

        <div style={s.iconRow}>
          <div style={s.icon}>
            <svg width="40" height="40" viewBox="0 0 36 36" fill="none">
              <rect width="36" height="36" rx="10" fill="#181922"/>
              <path d="M8 12C8 10.3431 9.34315 9 11 9H25C26.6569 9 28 10.3431 28 12V20C28 21.6569 26.6569 23 25 23H20L15 27V23H11C9.34315 23 8 21.6569 8 20V12Z" fill="#F5C518"/>
            </svg>
          </div>
          <div>
            <div style={s.appName}>BANQO</div>
            <div style={s.appSub}>Add to your home screen</div>
          </div>
        </div>

        <div style={s.desc}>
          Use Vert like a native app — no browser bar, instant access from your home screen.
        </div>

        {platform === 'ios' && (
          <div style={s.steps}>
            <div style={s.step}>
              <div style={s.stepNum}>1</div>
              <div style={s.stepText}>Tap the <strong style={{ color:'#F5C518' }}>Share</strong> button at the bottom of your Safari browser</div>
            </div>
            <div style={s.step}>
              <div style={s.stepNum}>2</div>
              <div style={s.stepText}>Scroll down and tap <strong style={{ color:'#F5C518' }}>"Add to Home Screen"</strong></div>
            </div>
            <div style={s.step}>
              <div style={s.stepNum}>3</div>
              <div style={s.stepText}>Tap <strong style={{ color:'#F5C518' }}>"Add"</strong> in the top right corner</div>
            </div>
            <div style={s.iosNote}>⚠️ Must be opened in Safari for this to work</div>
          </div>
        )}

        {platform === 'android' && (
          <button style={s.installBtn} onClick={installAndroid}>
            Add to Home Screen
          </button>
        )}

        {platform === 'desktop' && (
          <div style={s.steps}>
            <div style={s.step}>
              <div style={s.stepNum}>1</div>
              <div style={s.stepText}>Click the <strong style={{ color:'#F5C518' }}>install icon</strong> in your browser's address bar</div>
            </div>
            <div style={s.step}>
              <div style={s.stepNum}>2</div>
              <div style={s.stepText}>Click <strong style={{ color:'#F5C518' }}>"Install"</strong> to add Vert to your desktop</div>
            </div>
          </div>
        )}

        <button style={s.dismissBtn} onClick={dismiss}>maybe later</button>
      </div>
    </div>
  )
}

const s = {
  overlay: { position:'fixed', bottom:0, left:0, right:0, zIndex:9999, background:'rgba(0,0,0,0.6)', display:'flex', alignItems:'flex-end', justifyContent:'center', backdropFilter:'blur(4px)' },
  sheet: { background:'#22242f', borderRadius:'20px 20px 0 0', padding:'28px 24px 40px', width:'100%', maxWidth:480, border:'0.5px solid #2a2d3e', position:'relative' },
  closeBtn: { position:'absolute', top:16, right:16, background:'none', border:'none', color:'#888aa0', fontSize:18, cursor:'pointer', padding:4 },
  iconRow: { display:'flex', alignItems:'center', gap:14, marginBottom:16 },
  icon: { width:48, height:48, borderRadius:12, overflow:'hidden', flexShrink:0 },
  appName: { fontSize:20, fontWeight:700, color:'#ffffff', letterSpacing:'0.1em' },
  appSub: { fontSize:13, color:'#F5C518', fontFamily:"'DM Mono',monospace", marginTop:2 },
  desc: { fontSize:14, color:'#888aa0', lineHeight:1.6, marginBottom:20 },
  steps: { display:'flex', flexDirection:'column', gap:14, marginBottom:20 },
  step: { display:'flex', gap:12, alignItems:'flex-start' },
  stepNum: { width:26, height:26, borderRadius:8, background:'#F5C518', color:'#181922', fontSize:13, fontWeight:700, display:'flex', alignItems:'center', justifyContent:'center', flexShrink:0, marginTop:1 },
  stepText: { fontSize:14, color:'#ccc', lineHeight:1.5 },
  iosNote: { fontSize:12, color:'#888aa0', fontFamily:"'DM Mono',monospace", background:'#181922', padding:'8px 12px', borderRadius:8, marginTop:4 },
  installBtn: { width:'100%', padding:'14px', background:'#F5C518', border:'none', borderRadius:12, color:'#181922', fontSize:16, fontWeight:700, cursor:'pointer', fontFamily:"'Clarity City','DM Mono',sans-serif", marginBottom:12 },
  dismissBtn: { width:'100%', padding:'12px', background:'none', border:'none', color:'#888aa0', fontSize:14, cursor:'pointer', fontFamily:"'DM Mono',monospace" }
}
